from pathlib import Path
import json,base64,math
R=Path(__file__).resolve().parents[2];O=R/'renders/layouts_magenta_v1';base=json.loads((O/'manifest.json').read_text());extra=json.loads((O/'enhancements_manifest.json').read_text());lookup={e['id']:e for e in base['scenes']}
def uri(p):return 'data:image/png;base64,'+base64.b64encode(p.read_bytes()).decode()
data={}
for e in extra['scenes']+base['scenes']:
 isnew='parent' in e;p=O/('variantes' if isnew else 'zones')/e['id'];parent=lookup[e['parent']] if isnew else e;groups=e.get('animation_groups',[])
 if not isnew and e['animation']:groups=[{'name':'01_animation_reference','files':e['animation']['files'],'durations_ms':e['animation']['durations_ms'],'position':'under','origin':'séquence native, couleurs harmonisées'}]
 groups=[{**g,'images':[uri(p/f) for f in g['files']]} for g in groups];period=math.lcm(*[sum(g['durations_ms']) for g in groups]) if groups else 0;step=math.gcd(*[d for g in groups for d in g['durations_ms']]) if groups else 100
 data[e['id']]={'title':e['title'],'size':e['size'],'new':isnew,'layers':[{**l,'image':uri(p/l['file'])} for l in e['layers']],'groups':groups,'period':period,'step':step,'reference':uri(R/'source/layouts_magenta_v1/references'/(parent['biome']+'_reference.png')),'info':('Ajout demandé · ' if isnew else 'Variante de base · ')+('statique' if not groups else f'cycle complet{period}ms')}
h='''<!doctype html><html lang="fr"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>PMD · feuillages, siphons, irisations et lave</title><style>*{box-sizing:border-box}body{margin:0;background:#1c222a;color:#edf0e7;font:16px system-ui}header,main,footer{max-width:1400px;padding:24px;margin:auto}.tag{font-size:12px;letter-spacing:2px;color:#9bceb8}h1{font-size:28px;margin:8px 0}p{color:#c1cdd0;line-height:1.55}.bar{display:flex;gap:9px;flex-wrap:wrap;margin-bottom:20px}button,select{border:1px solid #65857f;border-radius:6px;background:#2d4247;color:#fff;padding:10px}.grid{display:grid;grid-template-columns:minmax(0,1fr) 320px;gap:24px}canvas{width:100%;max-height:77vh;object-fit:contain;object-position:top;image-rendering:pixelated;background:repeating-conic-gradient(#333940 0% 25%,#29323a 0% 50%) 50%/16px 16px}aside{padding:18px;background:#25343c;border-radius:7px;max-height:80vh;overflow:auto}label{display:block;font-size:14px;margin:13px 0}small{color:#b1c5c8}a{color:#a9e7ca}input[type=range]{width:100%}h3{font-size:16px;color:#daecdf}footer{border-top:1px solid #466562}@media(max-width:800px){.grid{grid-template-columns:1fr}aside{max-height:none}}</style><header><div class="tag">GÉNÉRATEUR SUR MAGENTA → CALQUES → ASSEMBLAGE ANIMÉ</div><h1>Feuillages immersifs · siphons d’eau · reflets irisés · lave</h1><p>Cinq ajouts conservant les layouts du premier lot. Chaque effet reste séparé ; les huit variantes de base sont également disponibles. Les nouvelles matières d’eau et de lave adaptent les séquences sources : elles ne sont pas présentées comme des animations natives retrouvées.</p></header><main><div class="bar"><select id="scene"></select><button id="all">Tous les calques</button><button id="none">Tout masquer</button><button id="ref">Référence source · phase0</button><button id="play">Pause</button><button id="step">+1 pas d’animation</button><button id="reset">Phase0</button><button id="save">Exporter la vue PNG</button></div><div class="grid"><section><canvas id="view"></canvas><p id="status"></p></section><aside><h3>Terrain / décor</h3><div id="layers"></div><h3>Animations indépendantes</h3><div id="groups"></div><label>Temps du cycle <input type="range" id="time" min="0" max="3900" value="0"></label><p id="clock"></p><small>Le bouton ↓ d’un groupe exporte sa phase courante. Les PNG de toutes les phases, les boucles WebP complètes et les documents ORA sont dans le pack.</small></aside></div></main><footer><p><b>Feuillage :</b> accès central dégagé. <b>Siphons :</b>6 phases adaptées. <b>Cristal :</b>12 phases de base +24 phases de reflets bleu–rose–blanc, RGB fixes et opacité variable. <b>Lave :</b>30 phases adaptées +30 phases de lueur de berge.</p><small>Roche « couleur centre » interprétée comme gris cendré. Les sols cachés sont reconstitués, les ombres de contact sont nouvelles ; les massifs ne constituent pas une bibliothèque d’objets complets occultés. Pas de validation PMDO/GPU.</small></footer><script>const DATA=__DATA__,sel=document.getElementById('scene'),c=document.getElementById('view'),ctx=c.getContext('2d');let e,ls=[],gs=[],on=[],gon=[],checks=[],gchecks=[],links=[],ref,showRef=false,playing=true,t=0,last=0;function image(src){const i=new Image();i.src=src;return i}for(const type of [true,false]){const group=document.createElement('optgroup');group.label=type?'Nouveaux ajouts':'Variantes de base conservées';for(const [id,x]of Object.entries(DATA))if(x.new===type){const o=document.createElement('option');o.value=id;o.textContent=x.title;group.append(o)}sel.append(group)}sel.value='cote_cendres_lave';function setup(){e=DATA[sel.value];t=0;showRef=false;ls=e.layers.map(l=>image(l.image));gs=e.groups.map(g=>g.images.map(image));on=ls.map(()=>true);gon=gs.map(()=>true);checks=[];gchecks=[];links=[];ref=image(e.reference);c.width=e.size[0];c.height=e.size[1];document.getElementById('layers').innerHTML='';document.getElementById('groups').innerHTML='';e.layers.forEach((l,i)=>{const row=document.createElement('label'),ch=document.createElement('input'),a=document.createElement('a');ch.type='checkbox';ch.checked=true;ch.onchange=()=>{on[i]=ch.checked;showRef=false};checks.push(ch);a.href=l.image;a.download=l.file;a.textContent=' ↓';row.append(ch,document.createTextNode(l.name.replace(/^\d+_/,'').replaceAll('_',' ')),a);document.getElementById('layers').append(row)});e.groups.forEach((g,i)=>{const row=document.createElement('label'),ch=document.createElement('input'),a=document.createElement('a');ch.type='checkbox';ch.checked=true;ch.onchange=()=>{gon[i]=ch.checked;showRef=false};gchecks.push(ch);a.textContent=' ↓';links.push(a);row.append(ch,document.createTextNode(g.name.replace(/^\d+_/,'').replaceAll('_',' ')+' · '+g.files.length+' phases'),a);document.getElementById('groups').append(row)});document.getElementById('time').max=Math.max(1,e.period-1);document.getElementById('time').disabled=!gs.length;document.getElementById('step').disabled=!gs.length;document.getElementById('status').textContent=e.info+' · '+e.size.join('×')}sel.onchange=setup;function visible(v){showRef=false;on.fill(v);gon.fill(v);checks.forEach(ch=>ch.checked=v);gchecks.forEach(ch=>ch.checked=v)}document.getElementById('all').onclick=()=>visible(true);document.getElementById('none').onclick=()=>visible(false);document.getElementById('ref').onclick=()=>{showRef=!showRef;playing=false;t=0;document.getElementById('play').textContent='Lecture'};document.getElementById('play').onclick=x=>{showRef=false;playing=!playing;x.target.textContent=playing?'Pause':'Lecture'};document.getElementById('step').onclick=()=>{showRef=false;playing=false;t+=e.step;document.getElementById('play').textContent='Lecture'};document.getElementById('reset').onclick=()=>{t=0;playing=false;showRef=false;document.getElementById('play').textContent='Lecture'};document.getElementById('time').oninput=x=>{t=+x.target.value;playing=false;showRef=false;document.getElementById('play').textContent='Lecture'};document.getElementById('save').onclick=()=>{const a=document.createElement('a');a.href=c.toDataURL();a.download=sel.value+'_vue.png';a.click()};function index(t,ds){t%=ds.reduce((a,b)=>a+b,0);let i=0;while(i<ds.length-1&&t>=ds[i])t-=ds[i++];return i}function draw(i){if(i.complete&&i.naturalWidth)ctx.drawImage(i,0,0)}function render(now){if(last&&playing)t+=Math.min(now-last,250);last=now;ctx.clearRect(0,0,c.width,c.height);const ids=e.groups.map(g=>index(t,g.durations_ms));ids.forEach((fi,i)=>{if(links[i]._fi!==fi){links[i].href=e.groups[i].images[fi];links[i].download=e.groups[i].files[fi];links[i]._fi=fi}});if(showRef)draw(ref);else{gs.forEach((arr,i)=>{if(gon[i]&&e.groups[i].position==='under')draw(arr[ids[i]])});ls.forEach((im,i)=>{if(on[i])draw(im)});gs.forEach((arr,i)=>{if(gon[i]&&e.groups[i].position==='over')draw(arr[ids[i]])})}document.getElementById('time').value=e.period?Math.floor(t%e.period):0;document.getElementById('clock').textContent=showRef?'Référence non modifiée · phase0':e.period?Math.floor(t%e.period)+' / '+e.period+' ms':'Composition statique';requestAnimationFrame(render)}setup();requestAnimationFrame(render);</script></html>'''
(R/'apercu_variantes_magenta_v1.html').write_text(h.replace('__DATA__',json.dumps(data)),encoding='utf8')
